import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 8 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"8","title":"Page 8 | Home","prev":"/page/7/","next":"/page/9/","posts":[{"title":"禁用页面滚动","url":"/posts/2022-03-13-scroll-lock/","date":"2022-03-13 15:11","tags":["web"],"html":"<p>在设计组件的时候，例如 Modal 弹窗组件，在显示组件的时候我们不希望页面可以滚动。这时候就需要临时禁用页面的滚动功能。接下来就讲解下禁用页面滚动的方法。</p>\\n<h2 id=\\"禁用滚动\\" tabindex=\\"-1\\">禁用滚动 <a class=\\"header-anchor\\" href=\\"#禁用滚动\\" aria-label=\\"Permalink to &quot;禁用滚动&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">document.body.style.</span><span style=\\"color:#6F42C1\\">setProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'overflow'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'hidden'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>禁用滚动的方法很简单，只需要在页面的 body 元素上设置 overflow 属性为 hidden，就可以禁用页面的滚动了。但是我们需要考虑到，如果我们的页面有滚动条，滚动条的消失会影响页面的显示效果。\\n所以完美的禁用滚动方式需要考虑到当前页面滚动条的宽度。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> getScrollbarWidth</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> scrollbarWidth</span><span style=\\"color:#D73A49\\"> =</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    window.innerWidth </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> document.documentElement.clientWidth;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> scrollbarWidth;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> lockBody</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> scrollbarWidth</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> getScrollbarWidth</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (scrollbarWidth) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    document.body.style.</span><span style=\\"color:#6F42C1\\">setProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'padding-right'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">\`\${</span><span style=\\"color:#24292E\\">scrollbarWidth</span><span style=\\"color:#032F62\\">}px\`</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  document.body.style.</span><span style=\\"color:#6F42C1\\">setProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'overflow'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'hidden'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br></div></div><p>为了保证不影响页面的显示效果，我们需要计算出当前页面滚动条的宽度，然后设置 body 的 padding-right 属性，这样就可以保证页面的显示效果。</p>\\n<h2 id=\\"恢复滚动\\" tabindex=\\"-1\\">恢复滚动 <a class=\\"header-anchor\\" href=\\"#恢复滚动\\" aria-label=\\"Permalink to &quot;恢复滚动&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> unlockBody</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  document.body.style.</span><span style=\\"color:#6F42C1\\">removeProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'overflow'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  document.body.style.</span><span style=\\"color:#6F42C1\\">removeProperty</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'padding-right'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>恢复滚动只需要把添加到 CSS 属性删除即可。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>如果一直使用 Mac 的触摸板来编程的话，有时候很难意识到滚动条的存在，但是对于大多数的 Windows 用户来说，滚动条会一直存在的。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/mantinedev/mantine/blob/master/src/mantine-hooks/src/use-scroll-lock/use-scroll-lock.ts\\" target=\\"_blank\\" rel=\\"noreferrer\\">use-scroll-lock.ts</a></p>\\n"},{"title":"Github 存储大文件","url":"/posts/2022-02-10-github-lfs/","date":"2022-02-10 23:16","tags":["github"],"html":"<p>最近在做项目的时候，需要上传一个超过 200MB 的数据库文件到 Github 上保存，结果 Github 提示文件过大。这才知道 Github 对单文件有 100 MB 的容量限制。</p>\\n<h2 id=\\"问题介绍\\" tabindex=\\"-1\\">问题介绍 <a class=\\"header-anchor\\" href=\\"#问题介绍\\" aria-label=\\"Permalink to &quot;问题介绍&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>正常情况下，我们执行 add, commit 操作的时候都没啥问题。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> .</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> commit</span><span style=\\"color:#005CC5\\"> -m</span><span style=\\"color:#032F62\\"> \\"add large file\\"</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>但是执行 push 操作的时候会返回错误。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> push</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Enumerating</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 21,</span><span style=\\"color:#032F62\\"> done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Counting</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (21/21), done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Delta</span><span style=\\"color:#032F62\\"> compression</span><span style=\\"color:#032F62\\"> using</span><span style=\\"color:#032F62\\"> up</span><span style=\\"color:#032F62\\"> to</span><span style=\\"color:#005CC5\\"> 10</span><span style=\\"color:#032F62\\"> threads</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Compressing</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (17/17), done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Writing</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (17/17), 153.95 MiB </span><span style=\\"color:#D73A49\\">|</span><span style=\\"color:#6F42C1\\"> 13.82</span><span style=\\"color:#032F62\\"> MiB/s,</span><span style=\\"color:#032F62\\"> done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Total</span><span style=\\"color:#005CC5\\"> 17</span><span style=\\"color:#24292E\\"> (delta </span><span style=\\"color:#005CC5\\">4</span><span style=\\"color:#24292E\\">), reused 0 (</span><span style=\\"color:#6F42C1\\">delta</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">), pack-reused 0</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> Resolving</span><span style=\\"color:#032F62\\"> deltas:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (4/4), completed with 3 </span><span style=\\"color:#D73A49\\">local</span><span style=\\"color:#24292E\\"> objects.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> error:</span><span style=\\"color:#032F62\\"> Trace:</span><span style=\\"color:#6A737D\\"> ###</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> error:</span><span style=\\"color:#032F62\\"> See</span><span style=\\"color:#032F62\\"> http://git.io/iEPt8g</span><span style=\\"color:#032F62\\"> for</span><span style=\\"color:#032F62\\"> more</span><span style=\\"color:#032F62\\"> information.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> error:</span><span style=\\"color:#032F62\\"> File</span><span style=\\"color:#032F62\\"> xxx.db</span><span style=\\"color:#032F62\\"> is</span><span style=\\"color:#005CC5\\"> 259.50</span><span style=\\"color:#032F62\\"> MB</span><span style=\\"color:#24292E\\">; </span><span style=\\"color:#6F42C1\\">this</span><span style=\\"color:#032F62\\"> exceeds</span><span style=\\"color:#032F62\\"> GitHub's file size limit of 100.00 MB</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">remote: error: GH001: Large files detected. You may want to try Git Large File Storage - https://git-lfs.github.com.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">To https://github.com/acgotaku/switch.git</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\"> ! [remote rejected] master -> master (pre-receive hook declined)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">error: failed to push some refs to 'https://github.com/{user}/{repo}.git'</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br></div></div><p>这里提示我们可以使用 Git Large File Storage 来解决。</p>\\n<h2 id=\\"安装-lfs\\" tabindex=\\"-1\\">安装 LFS <a class=\\"header-anchor\\" href=\\"#安装-lfs\\" aria-label=\\"Permalink to &quot;安装 LFS&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>根据官网的教程进行安装：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> brew</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> git-lfs</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>然后 cd 到对应的 repo：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> cd</span><span style=\\"color:#032F62\\"> {repo}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> lfs</span><span style=\\"color:#032F62\\"> install</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Updated</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> hooks.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Git</span><span style=\\"color:#032F62\\"> LFS</span><span style=\\"color:#032F62\\"> initialized.</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><h2 id=\\"重新提交\\" tabindex=\\"-1\\">重新提交 <a class=\\"header-anchor\\" href=\\"#重新提交\\" aria-label=\\"Permalink to &quot;重新提交&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>这时候我们需要保留文件的同时，取消 commit：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> cd</span><span style=\\"color:#032F62\\"> {REPO}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> reset</span><span style=\\"color:#005CC5\\"> --soft</span><span style=\\"color:#032F62\\"> HEAD^</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>然后单独提交大文件：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> lfs</span><span style=\\"color:#032F62\\"> track</span><span style=\\"color:#032F62\\"> {LARGE_FILE}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Tracking</span><span style=\\"color:#032F62\\"> {LARGE_FILE}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> .gitattributes</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>执行第一行命令之后会生成一个 <code>.gitattributes</code> 文件，记得这个也需要一并提交。</p>\\n<p>接下来执行普通的 add commit, push 三个步骤就可以了。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> .</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> commit</span><span style=\\"color:#005CC5\\"> -m</span><span style=\\"color:#032F62\\"> \\"add large file\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> push</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Github 针对大文件存储有一个月 1GB 流量的限制，所以如果到达限制了需要付费才能继续使用。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://qiita.com/kanaya/items/ad52f25da32cb5aa19e6\\" target=\\"_blank\\" rel=\\"noreferrer\\">GitHub に 100MB 超のファイルを置く</a></p>\\n"},{"title":"React 实现 Tabs 组件","url":"/posts/2022-01-27-react-tabs/","date":"2022-01-27 20:16","tags":["react"],"html":"<p>基于 Vue 框架来实现各种 UI 组件之前有讲过，并且讲述了复合组件如何传递数据。一种方式是使用 <code>Provide / inject</code>， 另外一种是传统的 <code>props</code> 和 <code>$emit()</code>。\\n但是 React 下复合组件如何实现，和 Vue 相比差距还是挺大的。接下来就讲述经典的 Tabs 组件如何来实现。</p>\\n<h2 id=\\"tabs-组件介绍\\" tabindex=\\"-1\\">Tabs 组件介绍 <a class=\\"header-anchor\\" href=\\"#tabs-组件介绍\\" aria-label=\\"Permalink to &quot;Tabs 组件介绍&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Tabs 是复合组件。<code>Tabs</code> 组件封装逻辑和显示上部的导航栏。 <code>TabPane</code> 用来传递属性和展示要显示的内容。具体使用请看下面的代码：</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#005CC5\\">Tabs</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#005CC5\\">TabPane</span><span style=\\"color:#6F42C1\\"> label</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\">\\"文档\\"</span><span style=\\"color:#6F42C1\\"> name</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\">\\"doc\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    文档</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;/</span><span style=\\"color:#005CC5\\">TabPane</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#005CC5\\">TabPane</span><span style=\\"color:#6F42C1\\"> label</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\">\\"快速起步\\"</span><span style=\\"color:#6F42C1\\"> name</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\">\\"start\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    快速起步</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;/</span><span style=\\"color:#005CC5\\">TabPane</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;</span><span style=\\"color:#005CC5\\">TabPane</span><span style=\\"color:#6F42C1\\"> label</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\">\\"帮助\\"</span><span style=\\"color:#6F42C1\\"> name</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\">\\"help\\"</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    帮助</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  &#x3C;/</span><span style=\\"color:#005CC5\\">TabPane</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;/</span><span style=\\"color:#005CC5\\">Tabs</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br></div></div><p>这里 TabPane 的两个属性，一个是用来展示 Tabs 的文本，一个用来标注组件的 <code>key</code>，所以 <code>name</code> 属性必须是独一无二的。</p>\\n<h2 id=\\"tabs-组件的实现\\" tabindex=\\"-1\\">Tabs 组件的实现 <a class=\\"header-anchor\\" href=\\"#tabs-组件的实现\\" aria-label=\\"Permalink to &quot;Tabs 组件的实现&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>React 框架可以通过 <code>children</code> 属性访问子组件，我们就利用这个特性来获取 TabPane 组件的相关属性。</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> interface</span><span style=\\"color:#6F42C1\\"> TabsProps</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  children</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">ReactNode</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  className</span><span style=\\"color:#D73A49\\">?:</span><span style=\\"color:#005CC5\\"> string</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> Tabs</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">FC</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">TabsProps</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> ({ </span><span style=\\"color:#E36209\\">children</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">className</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> ''</span><span style=\\"color:#24292E\\"> }) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">activeTab</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">setActiveTab</span><span style=\\"color:#24292E\\">] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> useState</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">''</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  useEffect</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#005CC5\\"> firstChild</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> React.Children.</span><span style=\\"color:#6F42C1\\">toArray</span><span style=\\"color:#24292E\\">(children)[</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (firstChild </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#24292E\\"> React.</span><span style=\\"color:#6F42C1\\">isValidElement</span><span style=\\"color:#24292E\\">(firstChild)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      setActiveTab</span><span style=\\"color:#24292E\\">(firstChild.props.name);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, [children]);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{</span><span style=\\"color:#6F42C1\\">cls</span><span style=\\"color:#24292E\\">(styles.tabs, className)}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{styles.tabsNav}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        {React.Children.</span><span style=\\"color:#6F42C1\\">map</span><span style=\\"color:#24292E\\">(children, </span><span style=\\"color:#E36209\\">child</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">          if</span><span style=\\"color:#24292E\\"> (React.</span><span style=\\"color:#6F42C1\\">isValidElement</span><span style=\\"color:#24292E\\">(child)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            const</span><span style=\\"color:#24292E\\"> { </span><span style=\\"color:#005CC5\\">name</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">label</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">disabled</span><span style=\\"color:#24292E\\"> } </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> child.props;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              &#x3C;</span><span style=\\"color:#22863A\\">button</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">                key</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{name}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">                className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{</span><span style=\\"color:#6F42C1\\">cls</span><span style=\\"color:#24292E\\">(styles.tabsNavButton, {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                  [styles.active]: name </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#24292E\\"> activeTab</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                })}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">                disabled</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{disabled}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">                onClick</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#6F42C1\\"> setActiveTab</span><span style=\\"color:#24292E\\">(name)}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              ></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                {label}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              &#x3C;/</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            return</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        })}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{styles.tabsContent}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        {React.Children.</span><span style=\\"color:#6F42C1\\">map</span><span style=\\"color:#24292E\\">(children, </span><span style=\\"color:#E36209\\">child</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">          if</span><span style=\\"color:#24292E\\"> (React.</span><span style=\\"color:#6F42C1\\">isValidElement</span><span style=\\"color:#24292E\\">(child)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            const</span><span style=\\"color:#24292E\\"> { </span><span style=\\"color:#005CC5\\">name</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">children</span><span style=\\"color:#24292E\\"> } </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> child.props;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            if</span><span style=\\"color:#24292E\\"> (name </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#24292E\\"> activeTab) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">              return</span><span style=\\"color:#24292E\\"> children;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">              return</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            return</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        })}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br></div></div><p>Tabs 组件负责维护 activeTab 状态，并且根据用户操作显示正确的 TabPane。相比之下 TabPane 组件的实现就非常简单：</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> interface</span><span style=\\"color:#6F42C1\\"> TabPaneProps</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  label</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> string</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  name</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> string</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  children</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">ReactNode</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  disabled</span><span style=\\"color:#D73A49\\">?:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  className</span><span style=\\"color:#D73A49\\">?:</span><span style=\\"color:#005CC5\\"> string</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> TabPane</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">FC</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">TabPaneProps</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> ({ </span><span style=\\"color:#E36209\\">children</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">className</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> ''</span><span style=\\"color:#24292E\\"> }) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> &#x3C;</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{</span><span style=\\"color:#6F42C1\\">cls</span><span style=\\"color:#24292E\\">(styles.tab, className)}>{children}&#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">>;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br></div></div><p>只是单纯的封装了一下要展示的内容而已。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>React 框架在实现复合组件的时候和 Vue 的方式有很大差异，不过 React 的逻辑看起来更加简单和易用。自己动手实现 UI 组件对于每个前端工程师来说都是成长道路上必不可少的一项技能，软件开发中没有银弹，我们不能总是依赖第三方 UI 库来实现界面。花费在适配第三方软件库的时间绝对不亚于自己手写一个组件的时间。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://semi.design/zh-CN/navigation/tabs\\" target=\\"_blank\\" rel=\\"noreferrer\\">Tabs 标签栏 - Semi Design</a></p>\\n"}]},"relativePath":"page/8/index.md","filePath":"page/[page].md"}`),l={name:"page/8/index.md"};function p(e,o,r,c,t,i){return n(),a("div")}const d=s(l,[["render",p]]);export{b as __pageData,d as default};
